# 📐 T-TRANCHE — «سجّل تجربة الدفعات» (العقد `tranche_prereg.md` + ملحق §⑨)
#    بحث/قياس فقط · الإنتاجُ لا يستوردها · الأقفال تحرس **عقدَ الأداة** لا رقمًا.
# ═══════════════════════════════════════════════════════════
import ast as _trn_ast
import contextlib as _trn_ctx
import importlib.util as _trn_imp
import io as _trn_io
import yaml as _trn_yaml

_trn_spec = _trn_imp.spec_from_file_location("tranche_arms", "tranche_arms.py")
_TRN = _trn_imp.module_from_spec(_trn_spec)
try:
    _trn_spec.loader.exec_module(_TRN)
    _trn_load = ""
except Exception as _e:                                          # noqa: BLE001
    _TRN, _trn_load = None, f"{type(_e).__name__}: {_e}"

check("📐🔒 TRN0 أداةُ الدفعات تُحمَّل بلا استيراد الإنتاج (بحث معزول)",
      _TRN is not None, _trn_load or "OK")

# 🔒 TRN1 — سلّمُ `P0` يطابق دفعاتِ الإنتاج **بت-بت** (وإلّا فالأساسُ مفبرَك)
_trn_df = synth_pivot(seed=2)
_trn_r = S.analyze_ticker("TRNX", _trn_df)
_trn_ok1 = bool(_trn_r) and _TRN is not None
_trn_l0 = None
if _trn_ok1:
    # 🔑 المِرساةُ من **دالّة الأداة** التي تنادي دوالَّ الإنتاج بالاسم — لا
    #    باسترجاعٍ بالقسمة. (‏2026-08-29: القفلُ القديم كان يستعمل **نفسَ**
    #    الاسترجاع المعطوب فيستحيل عليه أن يمسكه = «عيّنةٌ لا تفرّق» في القفل.)
    _trn_anch = _TRN.anchor_at(S, _trn_df, {"pivot": _trn_r.get("pivot")})
    _trn_l0 = (_TRN.ladder(_trn_anch, 0.0, S.CONFIG["ENTRY_TRANCHES"],
                           S.CONFIG["ENTRY_STEP_PCT"])
               if _trn_anch is not None else None)
    _trn_ok1 = _trn_l0 == [round(float(x), 2) for x in _trn_r["tranches"]]
check("📐🔒 TRN1 سلّمُ `P0` (إزاحة 0) = دفعاتُ الإنتاج بت-بت — بمِرساةِ الإنتاج",
      _trn_ok1,
      (f"{_trn_l0} مقابل {_trn_r['tranches']}" if _trn_ok1 is not True
       and bool(_trn_r) and _TRN is not None else "OK"))

# 🔒 TRN1ب — **بنيويّ**: `anchor_at` تنادي دالّتَي الإنتاج بالاسم · وصفرُ
#    استرجاعٍ للمِرساة بقسمةِ `rr_stop` في الأداة كلِّها (الصنفُ الذي أسقط
#    `TV1` في ثلاث تشغيلاتٍ حيّة قبل أيّ رقمِ ذراع).
_trn_ok1b = False
_trn_why1b = "لم تُحمَّل"
if _TRN is not None:
    _trn_src = _trn_io.open("tranche_arms.py", encoding="utf-8").read()
    _trn_t = _trn_ast.parse(_trn_src)
    _trn_fn = next((n for n in _trn_ast.walk(_trn_t)
                    if isinstance(n, _trn_ast.FunctionDef)
                    and n.name == "anchor_at"), None)
    _trn_names = ({getattr(c.func, "attr", None)
                   for c in _trn_ast.walk(_trn_fn) if isinstance(c, _trn_ast.Call)}
                  if _trn_fn is not None else set())
    # صفرُ قسمةٍ على `rr_stop` في أيّ موضعٍ من الأداة (تعبيرُ القسمة نحويًّا)
    _trn_div = [n for n in _trn_ast.walk(_trn_t)
                if isinstance(n, _trn_ast.BinOp)
                and isinstance(n.op, _trn_ast.Div)
                and "rr_stop" in _trn_ast.dump(n.left)]
    _trn_ok1b = (_trn_fn is not None and "_anchor_mode" in _trn_names
                 and "tested_level" in _trn_names and not _trn_div)
    _trn_why1b = (f"دوالّ={sorted(x for x in _trn_names if x)} "
                  f"قسماتُ rr_stop={len(_trn_div)}")
check("📐🔒 TRN1ب المِرساةُ من دوالّ الإنتاج بالاسم · صفرُ استرجاعٍ بقسمة `rr_stop`",
      _trn_ok1b, _trn_why1b)

# 🔒 TRN1ج — **العيّنةُ التي تفرّق** (حالةُ `ADTH/2023-01-05` الحيّة حرفيًّا):
#    مِرساةٌ 1.50 ⇒ `1.50 × 1.03 = 1.545` **على حدّ التدوير بالضبط**، والاسترجاعُ
#    بالقسمة يُزيحها **بوحدةِ ULP واحدة** فتعبر الحدَّ: ‏1.54 ⟶ 1.55.
#    ⇒ هذا هو الصنفُ الذي أسقط `TV1` — ولا تفرّقه العيّنةُ الصناعية إطلاقًا.
_trn_a0 = 1.50
_trn_rt = (_trn_a0 * (1 - 7 / 100.0)) / (1 - 7 / 100.0)          # الاسترجاعُ المعطوب
_trn_L_ok = [round(_trn_a0 * (1 + 0.03 * i), 2) for i in range(3)]
_trn_L_bad = [round(_trn_rt * (1 + 0.03 * i), 2) for i in range(3)]
check("📐🔒 TRN1ج عيّنةٌ **تفرّق**: الاسترجاعُ بالقسمة يعبر حدَّ التدوير (1.54 ⟶ 1.55)",
      (_trn_L_ok == [1.5, 1.54, 1.59] and _trn_L_bad == [1.5, 1.55, 1.59]
       and _trn_a0 != _trn_rt),
      f"سليم={_trn_L_ok} · مسترجَع={_trn_L_bad}")

# 🔒 TRN1د — **نقطةُ النداء الحيّة** (‏أُضيف 2026-09-01 بعد أن **نجت طفرةٌ**):
#    🔴 `TRN1`/`TRN1ب`/`TRN1ج` ثلاثتُها تحرس **الدالّةَ** `anchor_at` — وطفرةٌ
#    استبدلت **سطرَ ندائها** في `arms_for` باسترجاعٍ بالقسمة (‏`stop / 0.93`)
#    **نجت من الثلاثة**: جسمُ الدالّة سليمٌ فيمرّ `TRN1ب`، والقفلان الآخران
#    ينادِيانها **مباشرةً** فلا يمرّان بالمُنادي أصلًا. ⇒ **«الميزةُ موصولة»
#    تُثبَت من نقطة النداء لا من وجود الدالّة** (‏`wire-check` — والدرسُ وقع
#    في الجلسة التي وُثِّق فيها). فيُلزم هنا: `arms_for` تُسند `anchor` من
#    **نداءِ `anchor_at` وحدَه** (لا تعبيرَ حسابيّ) · وصفرُ قسمةٍ في جسمها.
_trn_ok1d = False
_trn_why1d = "لم تُحمَّل"
if _TRN is not None:
    _trn_af = next((n for n in _trn_ast.walk(_trn_ast.parse(_trn_src))
                    if isinstance(n, _trn_ast.FunctionDef)
                    and n.name == "arms_for"), None)
    if _trn_af is not None:
        _trn_asg = [n for n in _trn_ast.walk(_trn_af)
                    if isinstance(n, _trn_ast.Assign)
                    and any(getattr(t, "id", None) == "anchor" for t in n.targets)]
        # 🐞 **وتضييقٌ في اليوم نفسِه:** أوّلُ صياغةٍ منعت **كلَّ** قسمةٍ في
        #    `arms_for` فسقطت على `sum(trs) / len(trs)` — وهي **متوسّطُ الدفعات
        #    المشروع**. «قفلٌ يمنع الصحيحَ ليس أشدَّ — هو مكسور» ⇒ يُمنع
        #    **استرجاعُ مِرساةٍ** وحدَه: قسمةٌ طرفُها الأيسرُ يذكر وقفًا أو مِرساة.
        _trn_afdiv = [n for n in _trn_ast.walk(_trn_af)
                      if isinstance(n, _trn_ast.BinOp)
                      and isinstance(n.op, _trn_ast.Div)
                      and any(k in _trn_ast.dump(n.left)
                              for k in ("stop", "anchor", "rr_stop"))]
        _trn_ok1d = (len(_trn_asg) == 1
                     and isinstance(_trn_asg[0].value, _trn_ast.Call)
                     and getattr(_trn_asg[0].value.func, "id", None) == "anchor_at"
                     and not _trn_afdiv)
        _trn_why1d = (f"إسنادات anchor={len(_trn_asg)} · "
                      f"نوع={type(_trn_asg[0].value).__name__ if _trn_asg else '—'} "
                      f"· قسماتٌ في arms_for={len(_trn_afdiv)}")
    else:
        _trn_why1d = "arms_for غيرُ موجودة"
check("📐🔒 TRN1د نقطةُ النداء: `arms_for` تُسند المِرساةَ من `anchor_at` وحدَها "
      "(‏وصفرُ قسمةٍ فيها) — قفلُ الدالّةِ لا يحرس مُنادِيَها",
      _trn_ok1d, _trn_why1d)

# 🔒 TRN2 — الإزاحةُ ترفع السلّمَ فعلًا · وأدنى دفعةٍ تفارق الوقفَ (جوهرُ التجربة)
_trn_ok2 = False
if _TRN is not None:
    _a, _n, _st = 1.50, 3, 3.0
    _L0 = _TRN.ladder(_a, 0.0, _n, _st)
    _L1 = _TRN.ladder(_a, 2.0, _n, _st)
    _L3 = _TRN.ladder(_a, 7.0, _n, _st)
    # 🥇 و`P3` على مِرساةِ 1.50 يُعيد **مثالَ فيصل المنصوص حرفيًّا**:
    #    «‏1.50 قاع دخوله طلبات من **1.60 ل 1.70**» ⇒ [1.6, 1.65, 1.7].
    _trn_ok2 = (_L0 == [1.5, 1.54, 1.59] and _L1[0] > _L0[0]
                and _L3[0] > _L1[0] and abs(_L0[0] - round(_a, 2)) < 1e-9
                and _L3 == [1.6, 1.65, 1.7])
check("📐🔒 TRN2 الإزاحةُ ترفع بدايةَ السلّم · و`P0` يبدأ عند المِرساة بالضبط",
      _trn_ok2,
      (f"L0={_L0} L1={_L1} L3={_L3}" if _TRN is not None else "لم تُحمَّل"))

# 🔒 TRN3 — الوحدةُ الحاكمة **ثابتة**: مقامُها `entry(P0)` لا `entry` الذراع
#    (‏§④ — وإلّا كوفئت الإزاحةُ الأوسع بصِغَر مقامها = فخُّ T-RECLAIM-INTRADAY)
_trn_ok3 = False
if _TRN is not None:
    _fx = _TRN.r_fixed(10.0, 1.10, 1.03, 1.00)      # ذراعٌ أوسعُ دخولًا
    _ow = _TRN.r_own(10.0, 1.10, 1.00)
    _trn_ok3 = (abs(_fx - (0.10 * 1.10) / 0.03) < 1e-9
                and abs(_ow - (0.10 * 1.10) / 0.10) < 1e-9
                and _fx > _ow * 3)                   # الثابتةُ تعاقب الأوسع
check("📐🔒 TRN3 `r_fixed` مقامُها `entry(P0)` · و`r_own` مقامُها الذراع — وتفترقان",
      _trn_ok3,
      (f"fixed={_fx:.4f} own={_ow:.4f}" if _TRN is not None else "لم تُحمَّل"))


def _trn_rows(n_fill=100, n_nofill=20):
    """صفوفٌ صناعيّة بشكل الأداة الحقيقيّ: مِرساة 1.00 ⇒ `P0`=[1.00,1.03,1.06]
    ومتوسّطُه 1.03 ⇒ `R₀` = 0.03. تُستعمل لقفل معالجة `no_fill`."""
    out = []
    for k in range(n_fill + n_nofill):
        row = {"symbol": f"S{k}", "date": "2025-01-02", "stop": 1.00,
               "t1": 1.30, "anchor": 1.0, "pivot": 1.0,
               "prod_tr": [1.0, 1.03, 1.06], "tr0": [1.0, 1.03, 1.06],
               "prod_o": "win", "prod_ret": 3.0}
        for nm, off in _TRN.ARMS:
            L = _TRN.ladder(1.0, off, 3, 3.0)
            row[f"e_{nm}"] = round(sum(L) / len(L), 4)
            row[f"lo_{nm}"] = L[0]
            if k < n_fill:
                row[f"o_{nm}"] = "win"
                row[f"ret_{nm}"] = 3.0 + off        # تفرّقٌ حقيقيّ بين الأذرع
            else:
                row[f"o_{nm}"] = "no_fill"
                row[f"ret_{nm}"] = None
        out.append(row)
    return out


# 🔒 TRN4 — `no_fill` = صفرُ عائدٍ **ويدخل المقام** (‏§⑨-4): فالمقامُ واحدٌ
#    للأذرع الأربع وزيادةُ التعبئة تُحسَب لا تُخفى.
_trn_ok4, _trn_dbg4 = False, "لم تُحمَّل"
if _TRN is not None:
    _buf = _trn_io.StringIO()
    with _trn_ctx.redirect_stdout(_buf):
        _rc4 = _TRN.report(_trn_rows(), "2025", {},
                           {"n": 120, "n_diff": 0, "pct": 0.0,
                            "median_pct": 0.0, "max_pct": 0.0})
    _txt4 = _buf.getvalue()
    _sm4 = [ln for ln in _txt4.splitlines() if ln.strip().startswith("SUMMARY ")]
    if _rc4 == 0 and _sm4:
        _j4 = json.loads(_sm4[0].strip()[len("SUMMARY "):])
        _p0 = _j4["arms"]["P0"]
        _trn_ok4 = (_p0["n"] == 120 and _p0["n_fill"] == 100
                    and abs(_p0["fill_pct"] - 100 / 120 * 100) < 1e-6
                    and abs(_p0["r_fixed"] - (100 * (0.03 * 1.03 / 0.03)) / 120)
                    < 1e-6)
        _trn_dbg4 = (f"n={_p0['n']} fill={_p0['n_fill']} "
                     f"R0={_p0['r_fixed']:.6f}")
    else:
        _trn_dbg4 = f"rc={_rc4} summary={bool(_sm4)}"
check("📐🔒 TRN4 `no_fill`=0R **ويدخل المقام** — المقامُ واحدٌ للأذرع الأربع",
      _trn_ok4, _trn_dbg4)

