# ═══════════════════════════════════════════════════════════════════════════
import replay10 as RP

def _cand(sess, sym, seq, rdy=50.0, score=50.0, rr=1.0):
    return RP.Candidate(session=sess, symbol=sym, readiness=rdy, score=score, rr=rr, seq=seq)

