def _mf(rise, bars):
    """إطارٌ قمّتُه ترتفع `rise`% ثم يهبط `bars` جلسة — للتحكّم بالحالتين معًا."""
    hi = [1.0] * 5 + [1.0 * (1.0 + rise / 100.0)] + [1.0] * bars
    return S.pd.DataFrame({"High": hi},
                          index=S.pd.date_range("2024-01-01", periods=len(hi),
                                                freq="D"))


