def _fk(o, h, low, c, start="2026-01-01"):
    return S.pd.DataFrame(
        {"Open": o, "High": h, "Low": low, "Close": c, "Volume": [1e5] * len(o)},
        index=S.pd.date_range(start, periods=len(o), freq="B"))


