# FO9 · بصمةُ الحوافّ المدفوعة = المُصرَّح بها في الحارس
import envelope_bt as _fo_bt
import envelope_scan as _fo_es
# ✅ حُدِّث 2026-08-08: يقرأ **الملفَّ النافذ** (`EDGES_FILE`) لا اسمًا مغروسًا —
#    فحين بدّل المالك الحدَّ إلى `P100` بقي القفلُ حقيقيًّا بلا تعديلٍ ثانٍ.
_fo_blob = _fo_es.load_edges(_fo_es.EDGES_FILE)
_fo_blob.pop("_meta", None)          # ← `load_edges` تُرجع الحوافَّ **مسطَّحةً**
check("🎯 FO9 بصمةُ الملفّ النافذ = ثابتُ `V3` (مصدرٌ واحد)",
      bool(_fo_blob)
      and _fo_es.edges_fingerprint(_fo_blob) == _fo_bt.V3_FINGERPRINT,
      f"ملفّ={_fo_es.edges_fingerprint(_fo_blob) if _fo_blob else 'فارغ'} · "
      f"حارس={_fo_bt.V3_FINGERPRINT}")

# FO10 · تغطيةُ مسار الكلفة 100% (‏`ceil` لا `floor`)
_fo_step_src = None
for _n in _fo_ast.walk(_fo_ast.parse(open("catalog_envelope.py",
                                          encoding="utf-8").read())):
    if (isinstance(_n, _fo_ast.Assign) and _n.targets
            and getattr(_n.targets[0], "id", None) == "_step"):
        _fo_step_src = _fo_ast.unparse(_n.value)
_fo_u, _fo_cap = 3357, 600
try:
    _fo_step = eval(_fo_step_src, {"max": max},                   # noqa: S307
                    {"universe": [0] * _fo_u, "cap": _fo_cap})
except Exception:                                                 # noqa: BLE001
    _fo_step = None
check("🎯 FO10 مسارُ الكلفة يغطّي الكون 100% (تعبيرُ الإنتاج نفسُه)",
      _fo_step is not None and min(_fo_cap * _fo_step, _fo_u) >= _fo_u,
      f"step={_fo_step} · تغطية="
      f"{(min(_fo_cap * _fo_step, _fo_u) / _fo_u * 100) if _fo_step else 0:.1f}% "
      f"· التعبير={_fo_step_src}")

# FO11 · 🔴 **قفلٌ يقتل صنفَ العيب لا حالتَه:** `load_frozen_dataset` تُرجع **صفًّا**
#        `(hist, splits, asof)`. أيُّ مستهلكٍ يُسنده إلى اسمٍ واحد **ينهار** — وقد
#        وقع فعلًا في أوّل تشغيلةٍ حيّة. القفلُ يفحص **كلَّ** مستهلكٍ في المستودع.
_fo_cons = ["catalog_envelope.py", "envelope_bt.py", "faisal_only_check.py"]
_fo_bad = []
for _f in _fo_cons:
    for _n in _fo_ast.walk(_fo_ast.parse(open(_f, encoding="utf-8").read())):
        if not isinstance(_n, _fo_ast.Assign):
            continue
        _v = _n.value
        if (isinstance(_v, _fo_ast.Call)
                and getattr(_v.func, "attr", None) == "load_frozen_dataset"):
            _t = _n.targets[0]
            if not (isinstance(_t, (_fo_ast.Tuple, _fo_ast.List))
                    and len(_t.elts) == 3):
                _fo_bad.append(f"{_f}:{_n.lineno}")
check("🎯 FO11 كلُّ مستهلكٍ للقطة يفكُّ الصفَّ ثلاثيًّا (يقتل الصنف لا الحالة)",
      not _fo_bad, f"مخالفون={_fo_bad}")

# FO12 · 🔴 **مدخلٌ بلا `env` = مدخلٌ ميّت** — بصمةُ الـno-op التي وقعت في
#        `BT_CANDLE` (يُمرَّر بالـworkflow وغائبٌ عن جدول الإحلال ⇒ القيمةُ لا تُطبَّق
#        **والتشغيلةُ خضراء**). القفلُ يعمّم قاعدة P1 على `faisal_only.yml`:
#        ① كلُّ مدخلٍ يظهر في **قيمةِ** متغيّرِ بيئةٍ في خطوة التشغيل.
#        ② والاسمُ الذي تحمله الحوافُّ (`ENVELOPE_EDGES`) **هو الذي تقرؤه الأداة
#           فعلًا** — يُقرأ نحويًّا من `os.environ.get` لا نصًّا (فالتعليقُ لا يحرس).
import yaml as _fo_yaml                                          # noqa: E402
_fo_wf = _fo_yaml.safe_load(open(".github/workflows/faisal_only.yml",
                                encoding="utf-8"))
_fo_in = set((_fo_wf.get(True) or _fo_wf.get("on"))["workflow_dispatch"]["inputs"])
_fo_steps = _fo_wf["jobs"]["faisal-only"]["steps"]
_fo_env = {}
for _s in _fo_steps:
    if isinstance(_s.get("env"), dict):
        _fo_env.update(_s["env"])
_fo_envtxt = " ".join(str(v) for v in _fo_env.values())
_fo_dead = sorted(k for k in _fo_in if f"inputs.{k}" not in _fo_envtxt)
check("🎯 FO12-أ كلُّ مدخلٍ في faisal_only.yml موصولٌ بمتغيّرِ بيئة (لا مدخلَ ميّت)",
      not _fo_dead, f"ميّتة={_fo_dead} · مداخل={sorted(_fo_in)}")

# ② الاسمُ الذي يُمرَّر للحوافّ يجب أن يكون **نفسَه** الذي تقرؤه الأداة نحويًّا.
_fo_edge_env = sorted(k for k, v in _fo_env.items() if "inputs.edges" in str(v))
_fo_read = set()
for _n in _fo_ast.walk(_fo_ast.parse(open("faisal_only_check.py",
                                          encoding="utf-8").read())):
    if (isinstance(_n, _fo_ast.Call)
            and getattr(_n.func, "attr", None) == "get"
            and getattr(getattr(_n.func, "value", None), "attr", None) == "environ"
            and _n.args and isinstance(_n.args[0], _fo_ast.Constant)):
        _fo_read.add(_n.args[0].value)
check("🎯 FO12-ب اسمُ متغيّر الحوافّ يُقرأ فعلًا في faisal_only_check (وصلةٌ لا نيّة)",
      len(_fo_edge_env) == 1 and _fo_edge_env[0] in _fo_read,
      f"مُمرَّر={_fo_edge_env} · مقروءٌ نحويًّا={sorted(_fo_read)}")

