# 🔓 إقرارٌ مؤرَّخ 2026-08-20: الإبرةُ النصيّة العريضة («kasih2» في الملف كلِّه)
#    سقطت على اسم دالّة العرض `kasih2_wave_feats` («وسع الوسم») — والخطرُ
#    الحقيقيّ **الاستيرادُ** ⇒ صار الفحصُ على أسطر الاستيراد حصرًا (درسُ
#    «القفل النصّيّ لا يفرّق كودًا عن اسمٍ مشابه»).
check("🌊② K2L3 قراءةٌ فقط: صفرُ إرسال/كتابةِ حالة · والإنتاجُ لا يستورد kasih2_scan",
      _k2_bad == []
      and not any(_l.strip().startswith(("import kasih2_scan",
                                         "from kasih2_scan"))
                  for _l in open("Super_stock.py",
                                 encoding="utf-8").read().splitlines()),
      f"سيئ={_k2_bad}")

# K2L4 — وصلُ الـworkflow نحويًّا (نمطُ KAS5 حرفيًّا على kasih2.yml).
_k22_wf = _fo_yaml.safe_load(open(".github/workflows/kasih2.yml",
                                  encoding="utf-8"))
_k22_on = (_k22_wf.get(True) or _k22_wf.get("on") or {})
_k22_env = {}
for _s in _k22_wf["jobs"]["kasih"]["steps"]:
    if isinstance(_s.get("env"), dict):
        _k22_env.update(_s["env"])
_k22_reads = {n.args[0].value for n in _ast0.walk(_k2_tree)
              if isinstance(n, _ast0.Call)
              and getattr(n.func, "attr", None) == "get"
              and getattr(getattr(n.func, "value", None), "attr", None) == "environ"
              and n.args and isinstance(n.args[0], _ast0.Constant)}
_k22_run = " ".join(str(_s.get("run") or "")
                    for _s in _k22_wf["jobs"]["kasih"]["steps"])
check("🌊② K2L4 kasih2.yml موصول: المدخلان ⟵ بيئةٌ يقرؤها السكربت · يشغّل "
      "kasih2_scan · بلا كرون · قراءةُ contents فقط",
      set(_k22_on.get("workflow_dispatch", {}).get("inputs", {}))
      == {"year", "day"}
      and "schedule" not in _k22_on
      and _k22_wf.get("permissions") == {"contents": "read"}
      and "inputs.year" in str(_k22_env.get("KASIH_YEAR"))
      and "inputs.day" in str(_k22_env.get("KASIH_DAY"))
      and "POLYGON_S3_KEY" in str(_k22_env.get("AWS_ACCESS_KEY_ID"))
      and "kasih2_scan.py" in _k22_run
      and {"KASIH_YEAR", "KASIH_DAY", "AWS_ACCESS_KEY_ID"} <= _k22_reads,
      f"reads={sorted(_k22_reads & {'KASIH_YEAR', 'KASIH_DAY'})}")

# K2L5 — الصفُّ يحمل الرفيقَ ومفاتيحَ الخصائص كلَّها (وصلةٌ حيّة لا متخيَّلة):
#   k2_features على عيّنةٍ غنيّةٍ يملأ الأحد عشر مفتاحًا — والمِرساةُ الغائبة ⇒ {}.
_k2_feats = _K2.k2_features(_k2_rows, 10 * _k2M, 1.29, "operator", 45.0,
                            1.29 * 40_000, _K2.KS.f2_usd5(_k2_rows, 10 * _k2M))
# K2L6 — 💵 `entry_view` (وضعُ اليوم: «لو دخلت على كم؟») **يطابق حسمَ
#   `resolve` بوليانيًّا** على عيّناتٍ مفرِّقة (كاسحٌ من د5 · وميّتٌ من د5)،
#   و`e5` = **إغلاقُ الدقيقة الخامسة** = سعرُ كرت M5 حرفيًّا.
_k2M2 = 60_000
_k2a2 = 10 * _k2M2
_k2_sweep = [(_k2a2, 1.00, 1.30, 1.00, 1.29, 40000),
             (_k2a2 + _k2M2, 1.29, 1.36, 1.28, 1.35, 44100),
             (_k2a2 + 2 * _k2M2, 1.35, 1.40, 1.34, 1.39, 50000),
             (_k2a2 + 3 * _k2M2, 1.39, 1.42, 1.38, 1.41, 60000),
             (_k2a2 + 4 * _k2M2, 1.41, 1.44, 1.40, 1.43, 70000),
             (_k2a2 + 5 * _k2M2, 1.43, 1.95, 1.42, 1.90, 80000)]
_k2_dead = [(_k2a2, 1.00, 1.30, 1.00, 1.29, 40000),
            (_k2a2 + _k2M2, 1.29, 1.31, 1.28, 1.30, 20000),
            (_k2a2 + 2 * _k2M2, 1.30, 1.31, 1.29, 1.30, 18000),
            (_k2a2 + 3 * _k2M2, 1.30, 1.31, 1.29, 1.30, 16000),
            (_k2a2 + 4 * _k2M2, 1.30, 1.31, 1.29, 1.30, 14000),
            (_k2a2 + 5 * _k2M2, 1.30, 1.31, 1.29, 1.30, 12000)]
_k2_ev_ok = True
_k2_ev_det = []
for _nm, _rr in (("كاسح", _k2_sweep), ("ميّت", _k2_dead)):
    _e = _K2.entry_view(_rr, _k2a2, 1.29, 0.70)
    _rs = _K2.KS.resolve(_rr, _k2a2, 1.29)
    _same = (_e is not None and _e["mg5"] is not None
             and (_e["mg5"] >= _K2.KS.KASIH_PCT)
             == bool(_rs.get("kasih30_from5")))
    _k2_ev_det.append(f"{_nm}: mg5={_e and round(_e['mg5'], 1)} "
                      f"حسم={_rs.get('kasih30_from5')}")
    _k2_ev_ok = _k2_ev_ok and _same
_k2_ev1 = _K2.entry_view(_k2_sweep, _k2a2, 1.29, 0.70)
check("🌊② K2L6 💵 `entry_view` يطابق حسمَ `resolve` (كاسحٌ وميّتٌ يفترقان) · "
      "و`e5` = إغلاقُ الدقيقة الخامسة · والنسبةُ من إغلاق الأمس",
      _k2_ev_ok and abs(_k2_ev1["e5"] - 1.43) < 1e-9
      and abs(_k2_ev1["gap5"] - 104.2857) < 0.01
      and _K2.entry_view(_k2_sweep, 999, 1.29, 0.70) is None,
      " · ".join(_k2_ev_det))

check("🌊② K2L5 k2_features يملأ المفاتيح الأحد عشر · ومِرساةٌ غائبة ⇒ {} بلا انهيار",
      set(_k2_feats) == {"j1", "j1_cell", "c1", "c2", "c3", "c4",
                         "v1", "v2", "v3", "p1", "p2"}
      and all(_k2_feats[k] is not None for k in ("j1", "c1", "c2", "v2", "p1"))
      and _K2.k2_features(_k2_rows, 999, 1.29, "mid", 5.0, 1, 1) == {},
      f"مفاتيح={sorted(_k2_feats)}")

# ═══ 🌊② «وسع الوسم» — KAS11-KAS14 (أمر المالك 2026-08-20 بعد حكم kasih2) ═══
# مؤشّراتُ المواصلة الأربع (C3/C4/V2/V3) + شارةُ «التوليفة» على كرت M5 —
# عرضٌ فقط: k2 حقلٌ إضافيٌّ بحت والإطلاقُ بت-بت.

# KAS11 — تكافؤُ الإنتاج مع أداة القياس **سلوكيًّا** على عيّناتٍ مفرِّقة
#   (المقياسُ واحدٌ وإن امتنع الاستيراد — عقد K2L3):
def _kwb(t, o, c, v):
    return {"t": t, "o": o, "h": max(o, c), "l": min(o, c), "c": c, "v": v}


def _kwt(bars):
    return [(int(b["t"]), b["o"], b["h"], b["l"], b["c"], b["v"])
            for b in bars]


_kw_a = 600_000
_kw_rich = [_kwb(_kw_a, 1.00, 1.29, 40_000),
            _kwb(_kw_a + 60_000, 1.29, 1.35, 44_100),
            _kwb(_kw_a + 120_000, 1.35, 1.39, 50_000),
            _kwb(_kw_a + 180_000, 1.39, 1.41, 60_000),
            _kwb(_kw_a + 240_000, 1.41, 1.43, 70_000)]
_kw_drain = [_kwb(_kw_a, 1.00, 1.29, 40_000),
             _kwb(_kw_a + 60_000, 1.29, 1.26, 10_000),
             _kwb(_kw_a + 120_000, 1.26, 1.21, 4_000)]
_kw_gap = [_kwb(_kw_a, 1.00, 1.29, 40_000),
           _kwb(_kw_a + 240_000, 1.29, 1.40, 50_000)]
_kw_ok = True
for _nm, _bars in (("غنية", _kw_rich), ("نازحة", _kw_drain),
                   ("مفجوّة", _kw_gap)):
    _p = S.kasih2_wave_feats(_bars, _kw_a, 1.29)
    _t = {"c3": _K2.c3_bucket(_kwt(_bars), _kw_a, 1.29),
          "c4": _K2.c4_bucket(_kwt(_bars), _kw_a),
          "v2": None, "v3": _K2.v3_bucket(_kwt(_bars), _kw_a)}
    _u5 = sum(b["c"] * b["v"] for b in _bars)
    _t["v2"] = _K2.v2_bucket(_bars[0]["c"] * _bars[0]["v"], _u5)
    if _p != _t:
        _kw_ok = False
        break
_kw_legacy = S.kasih2_wave_feats(_kw_rich, _kw_a, None)
check("🌊② KAS11 تكافؤُ الإنتاج مع kasih2_scan سلوكيًّا (غنية/نازحة/مفجوّة) · "
      "وحالةٌ قديمة بلا سعر ⇒ c3 وحدها None",
      _kw_ok and _kw_legacy.get("c3") is None
      and _kw_legacy.get("c4") == "خضراء 3-4"
      and "داخلة" in (_kw_legacy.get("v3") or ""),
      f"تكافؤ={_kw_ok} قديمة={_kw_legacy}")

# KAS12 — الوصلةُ الحيّة: حدثُ M5 من liq_stage_events يحمل k2 · وM30 **يرثه**
#   من الحالة · والمراحلُ المُطلَقة كما هي (عرضٌ لا إطلاق).
# 🥇 **إقرارٌ مؤرَّخ 2026-08-26 (أمرُ المالك «والثلاثين للقوي» ثم «اعتمد v1»):**
#   كان القفلُ يشترط «‏M30 بلا k2» — وذلك بعينه ما جعل `liq_tier` ترجع `None`
#   لكرت الثلاثين فيمرّ **الجميعُ** بوّابةَ «القوي فقط» بفائدة الشك ⇒ انقلب
#   العقدُ: **M30 يرث ختمَ M5 نفسَه** (عبر الحالة `st["k2"]` — سلسلةُ الإنتاج
#   `_kw_r1/r2/r3` حرفيًّا لا حقنًا) فيصير قابلًا للتصنيف والفلترة.
_kw_r1 = ([_kwb(i * 60_000, 1.0, 1.0, 1000) for i in range(10)]
          + [_kwb(600_000, 1.0, 1.10, 300000),
             _kwb(660_000, 1.10, 1.10, 10)])
_kw_e1, _kw_st = S.liq_stage_events(_kw_r1, {})
_kw_r2 = (_kw_r1[:-1]
          + [_kwb(660_000, 1.10, 1.12, 330100),
             _kwb(720_000, 1.12, 1.14, 380000),
             _kwb(780_000, 1.14, 1.15, 420000),
             _kwb(840_000, 1.15, 1.16, 460000),
             _kwb(900_000, 1.16, 1.17, 10)])
_kw_e2, _kw_st2 = S.liq_stage_events(_kw_r2, dict(_kw_st))
_kw_m5 = next((e for e in _kw_e2 if e.get("stage") == "M5"), {})
_kw_r3 = (_kw_r2[:-1]
          + [_kwb((10 + k) * 60_000, 1.16, 1.16, 500)
             for k in range(5, 31)]
          + [_kwb(41 * 60_000, 1.16, 1.16, 10)])
_kw_e3, _ = S.liq_stage_events(_kw_r3, dict(_kw_st2))
_kw_m30 = next((e for e in _kw_e3 if e.get("stage") == "M30"), {})
check("🌊② KAS12 حدثُ M5 يحمل k2 بمؤشّراته من مسار الإنتاج · وM30 **يرثه** "
      "(الختمُ نفسُه عبر الحالة)",
      isinstance(_kw_m5.get("k2"), dict)
      and _kw_m5["k2"].get("c4") == "خضراء 3-4"
      and "داخلة" in (_kw_m5["k2"].get("v3") or "")
      and _kw_m30.get("stage") == "M30"
      and _kw_m30.get("k2") == _kw_m5["k2"],
      f"M5.k2={_kw_m5.get('k2')} · M30.k2={_kw_m30.get('k2')}")

# KAS13 — العرضُ يفرّق: شارةُ «التوليفة» عند (قوي/مضارب × فجوة 30 فأكثر)
#   **حصرًا** · ولاحقةُ أقوى خليةٍ عند (قوي × فوق 75) حصرًا · وسطرُ المؤشّرات
#   يظهر مع k2 ويغيب بدونه · **والقراءةُ السالبة تُعرَض** (نقضت بنسبتها).
_kw_ev = {"stage": "M5", "class": ("strong", "x"), "anchor_price": 1.29,
          "prev_close": 0.70, "anchor_ms": _kw_a,
          "k2": S.kasih2_wave_feats(_kw_rich, _kw_a, 1.29)}
_kw_l1 = S.kasih_tag_line(_kw_ev)
_kw_l2 = S.kasih_tag_line(dict(_kw_ev, prev_close=1.00))     # فجوة 29% ⇒ بلا شارة
_kw_l3 = S.kasih_tag_line(dict(_kw_ev, **{"class": ("mid", "x")}))
_kw_l4 = S.kasih_tag_line(dict(_kw_ev, prev_close=0.95))     # 35.8% ⇒ شارة بلا لاحقة
_kw_l5 = S.kasih_tag_line({k: v for k, v in _kw_ev.items() if k != "k2"})
_kw_l6 = S.kasih_tag_line(dict(_kw_ev,
                               k2=S.kasih2_wave_feats(_kw_drain, _kw_a, 1.29)))
check("🌊② KAS13 شارةُ التوليفة تفرّق (30% حدًّا · قوي/مضارب حصرًا) · واللاحقةُ "
      "عند قوي×فوق75 حصرًا · والمؤشّراتُ مع k2 وحده · والسالبةُ تُعرَض",
      # ⚖️ **إقرارٌ مؤرَّخ 2026-08-20 (الاختصار):** الشارةُ انتقلت إلى **رأس
      #    الكرت** عبر `kasih_j1` (قاعدةٌ واحدة)، والمؤشّراتُ الأربعة ضُغطت إلى
      #    **عدّاد** «مواصلة ن من م» يُوسَم ⚠️ عند الصفر (سندُه `red_mute_result`:
      #    صفرُ أخضرَ كاسحُه 3.4-4.0% مقابل 14-17%). **والتفريقُ يُقاس الآن على
      #    `kasih_j1` نفسِها** — وهي موضعُ القرار الوحيد.
      S.kasih_j1(_kw_ev) == (True, True)
      and S.kasih_j1(dict(_kw_ev, prev_close=1.00))[0] is False
      and S.kasih_j1(dict(_kw_ev, **{"class": ("mid", "x")}))[0] is False
      and S.kasih_j1(dict(_kw_ev, prev_close=0.95)) == (True, False)
      and S.kasih_j1({}) == (False, False)
      and "مواصلة" in _kw_l1 and "مواصلة" not in _kw_l5
      and "نقضت" not in _kw_l6 and "5.3-6.3%" not in _kw_l6
      and "مواصلة" in _kw_l6)

# KAS14 — النِّسبُ الجديدة مقفولةٌ ازدواجيًّا على أرقام kasih2_result المنشورة
#   (نمطُ _k9_pub): تعديلُ أيٍّ منها بلا تعديل القفل = سقوط.
_kw_pub = {
    ("j1", "توليفة"): (19.7, 22.6), ("j1", "الباقي"): (7.7, 9.3),
    ("c3", "صادقت (إغلاقٌ فوق المرساة)"): (18.5, 22.0),
    ("c3", "حيّدت"): (9.5, 9.8), ("c3", "نقضت"): (5.3, 6.3),
    ("c4", "خضراء 3-4"): (24.2, 29.3), ("c4", "خضراء 2"): (11.0, 14.1),
    ("c4", "خضراء 0-1"): (4.8, 5.5),
    ("v2", "المرساة دون 30% (سيولة تتوالى)"): (18.1, 22.2),
    ("v2", "المرساة 30-60% من الخمس"): (6.5, 6.7),
    ("v2", "المرساة فوق 60% من الخمس (اندفاعة وحيدة)"): (4.8, 6.0),
    ("v3", "سيولةٌ داخلة (نبضٌ صافٍ موجب)"): (23.6, 32.6),
    ("v3", "نبضٌ متعادل"): (11.2, 12.4),
    ("v3", "سيولةٌ نازحة (نبضٌ صافٍ سالب)"): (6.5, 7.1),
}
_kw_dup = all(S.KASIH_RATES[f][b] == r for (f, b), r in _kw_pub.items())
check("🌊② KAS14 نِسبُ التوسيع مقفولةٌ ازدواجيًّا على kasih2_result (‏14 صفًّا "
      "+ أقوى خلية)",
      _kw_dup and S.KASIH_RATES["j1_top"] == (27.9, 37.1)
      and all(b in S.KASIH_RATES[f] for (f, b) in _kw_pub),
      f"ازدواج={_kw_dup}")

# ═══ 🔴🔇 «اكتم الأحمر» — أقفال RED1-RED4 (عقد red_mute_prereg.md · 2026-08-20) ═══
# أداةُ الإحصاء kasih2_red_stats.py: تعريفُ «الأحمر» يفرّق (RED1) · قراءةٌ فقط
# (RED2) · وصلُ الـworkflow (RED3) · وسلالُ العليا تطابق kasih2_scan سلوكيًّا (RED4).
import kasih2_red_stats as _RS

# RED1 — التعريفُ بنصّ العقد §① يفرّق على أربع حالاتٍ حدّية:
#   4 محسوبةٍ سفلى ⇒ أحمر · 3 محسوبةٍ سفلى (الرابعة None) ⇒ أحمر ·
#   3 محسوبةٍ إحداها عليا ⇒ ليس أحمر · 2 محسوبةٍ فقط ⇒ يمرّ بفائدة الشك.
_rs_low = {"c3": "نقضت", "c4": "خضراء 0-1",
           "v2": "المرساة فوق 60% من الخمس (اندفاعة وحيدة)",
           "v3": "سيولةٌ نازحة (نبضٌ صافٍ سالب)"}
check("🔴🔇 RED1 «الأحمر» يفرّق: ‏4 سفلى=أحمر · 3 سفلى=أحمر · عليا واحدة=لا · "
      "‏2 محسوبة=يمرّ بفائدة الشك",
      _RS.is_red(dict(_rs_low)) is True
      and _RS.is_red({**_rs_low, "c3": None}) is True
      and _RS.is_red({**_rs_low, "c4": "خضراء 3-4"}) is False
      and _RS.is_red({**_rs_low, "c3": None,
                      "v3": "سيولةٌ داخلة (نبضٌ صافٍ موجب)"}) is False
      and _RS.is_red({**_rs_low, "c3": None, "v2": None}) is False)

# RED2 — قراءةٌ فقط: صفرُ إرسال/كتابةِ حالة/فتحٍ للكتابة (AST) · والإنتاجُ لا
#   يستورد الأداة.
_rs_tree = _ast0.parse(_insp0.getsource(_RS))
_rs_bad = [getattr(n.func, "attr", getattr(n.func, "id", None))
           for n in _ast0.walk(_rs_tree) if isinstance(n, _ast0.Call)
           if (getattr(n.func, "attr", getattr(n.func, "id", "")) or "")
           in ("send_telegram", "save_watchlist", "save_op_entry_state",
               "git_save")]
_rs_wopen = []
for _n in _ast0.walk(_rs_tree):
    if (isinstance(_n, _ast0.Call)
            and getattr(_n.func, "id", None) == "open"):
        _md = ""
        if len(_n.args) >= 2 and isinstance(_n.args[1], _ast0.Constant):
            _md = str(_n.args[1].value)
        for _kw in _n.keywords:
            if _kw.arg == "mode" and isinstance(_kw.value, _ast0.Constant):
                _md = str(_kw.value.value)
        if any(ch in _md for ch in "wax+"):
            _rs_wopen.append(_md)
check("🔴🔇 RED2 قراءةٌ فقط: صفرُ إرسال/كتابة (AST) · والإنتاجُ لا يستورد الأداة",
      _rs_bad == [] and _rs_wopen == []
      and not any(_l.strip().startswith(("import kasih2_red_stats",
                                         "from kasih2_red_stats"))
                  for _l in open("Super_stock.py",
                                 encoding="utf-8").read().splitlines()),
      f"سيئ={_rs_bad} كتابة={_rs_wopen}")

# RED3 — وصلُ الـworkflow نحويًّا (نمط K2L4 على kasih2_red.yml): المدخلُ ⟵
#   بيئةٌ يستهلكها التنزيل · صلاحياتُ قراءةٍ فقط (contents+actions) · بلا كرون ·
#   يشغّل أداةَ الإحصاء بعد `gh run download`.
_red_wf = _fo_yaml.safe_load(open(".github/workflows/kasih2_red.yml",
                                  encoding="utf-8"))
