# 🕐📡 **PGP1-PGP5 — مِجَسُّ «فجوة المزوّد»** (أمرُ المالك «قس فجوة المزود»
#    2026-08-26 بعد حالة `$CRE`: شمعةٌ أغلقت 11:42:00 ومسحتانا لم تجداها
#    والتُقطت 11:44:04). قراءةٌ فقط · جالبُ الإنتاج بالاسم · عيّنةٌ تفرّق.
# ════════════════════════════════════════════════════════════════════════
import provider_gap_probe as _PGP                                 # noqa: E402
import io as _io_pg                                               # noqa: E402
from contextlib import redirect_stdout as _rd_pg                  # noqa: E402
import yaml as _yaml_pg                                           # noqa: E402

# PGP1 — 🔒 قراءةٌ فقط بالـAST: صفرُ نداءِ إرسالٍ/كتابةِ حالةٍ وصفرُ open-كتابة.
_pgp_src = _insp0.getsource(_PGP)
_pgp_tree = _ast_t3.parse(_pgp_src)
_pgp_bad = [getattr(c.func, "attr", None) or getattr(c.func, "id", None)
            for c in _ast_t3.walk(_pgp_tree) if isinstance(c, _ast_t3.Call)
            and (getattr(c.func, "attr", None) or getattr(c.func, "id", None))
            in ("send_telegram", "git_save", "save_watchlist")]
_pgp_wopen = [c for c in _ast_t3.walk(_pgp_tree) if isinstance(c, _ast_t3.Call)
              and getattr(c.func, "id", None) == "open"
              and any(isinstance(a, _ast_t3.Constant) and "w" in str(a.value)
                      for a in c.args[1:2])]
check("🕐 PGP1 المِجَسُّ قراءةٌ فقط (صفرُ إرسالٍ وكتابةِ حالةٍ بالـAST)",
      not _pgp_bad and not _pgp_wopen,
      f"نداءات={_pgp_bad} كتابة={len(_pgp_wopen)}")

# PGP2 — 🔒 **مقياسٌ واحد**: الجالبُ جالبُ الإنتاج `polygon_minute_bars`
#   بالاسم (Attribute بالـAST) — ولا URL محلّيًّا ولا `requests` (نسخةٌ ثانية
#   من الجلب = ما يراه المِجَسُّ غيرُ ما يراه الإنتاج).
_pgp_attr = [n for n in _ast_t3.walk(_pgp_tree)
             if isinstance(n, _ast_t3.Attribute)
             and n.attr == "polygon_minute_bars"]
_pgp_imp = {a.name.split(".")[0] for n in _ast_t3.walk(_pgp_tree)
            if isinstance(n, (_ast_t3.Import,))
            for a in n.names} | {n.module.split(".")[0]
                                 for n in _ast_t3.walk(_pgp_tree)
                                 if isinstance(n, _ast_t3.ImportFrom)
                                 and n.module}
check("🕐 PGP2 الجالبُ `bot.polygon_minute_bars` بالاسم · ولا URL ولا requests",
      len(_pgp_attr) >= 1 and "v2/aggs" not in _pgp_src
      and "requests" not in _pgp_imp,
      f"attr={len(_pgp_attr)} imports={sorted(_pgp_imp)}")

# PGP3/PGP4 — 🔒 **سلوكيًّا بعيّنةٍ تفرّق** (مخطّطُ الدخان المثبَّت): البدء
#   1060ث · A أغلقت 1000 (قبل البدء ⟸ خارج المقام) · B تظهر آخرَ صفٍّ (ظهور
#   10ث) ثم تدخل rows[:-1] (تقييم 15ث — **بعد** الظهور بالبناء) · C تبقى
#   آخرَ صفٍّ ⟸ «ظهرت ولم تصر قابلةً» = 1.
_pgp_resp = [
    [{"t": 940_000}],
    [{"t": 940_000}, {"t": 1_000_000}],
    [{"t": 940_000}, {"t": 1_000_000}, {"t": 1_060_000}],
    [{"t": 1_000_000}, {"t": 1_060_000}],
]
_pgp_clk = {"t": 1060.0, "n": 0}


def _pgp_clock():
    return _pgp_clk["t"]


def _pgp_sleep(s):
    _pgp_clk["t"] += s


def _pgp_fetch(sym, minutes=30):
    i = min(_pgp_clk["n"], len(_pgp_resp) - 1)
    _pgp_clk["n"] += 1
    _pgp_clk["t"] += 5.0
    return _pgp_resp[i]


_pgp_buf = _io_pg.StringIO()
try:
    with _rd_pg(_pgp_buf):
        _pgp_rc = _PGP.run(fetch=_pgp_fetch, clock=_pgp_clock,
                           sleep=_pgp_sleep, syms=["T1"],
                           run_min=(4 * 8) / 60.0, poll_sec=3.0)
except Exception as _e:                                          # noqa: BLE001
    _pgp_rc = f"⛔ رمى: {type(_e).__name__}"
_pgp_out = _pgp_buf.getvalue()
check("🕐 PGP3 التقييمُ (rows[:-1]) **بعد** الظهور: ظهورُ B عند 10ث وتقييمُها "
      "عند 15ث · والعالقةُ آخرَ صفٍّ تُعَدّ «لم تصر قابلة»",
      _pgp_rc == 0 and "أقصى 10.0ث" in _pgp_out
      and "وسيط 15.0ث" in _pgp_out
      and "ظهرت ولم تصر قابلةً للتقييم حتى النهاية: 1" in _pgp_out,
      f"rc={_pgp_rc} · {_pgp_out[-260:]}")
with _rd_pg(_io_pg.StringIO()):
    _pgp_rc4 = _PGP._report({}, {}, {}, [1.0], ["T1"], 0.0, 60.0)
check("🕐 PGP4 ما أغلق قبل البدء **خارج المقام** (A مستبعَدة ⟸ الظهور n=2 "
      "لا 3) · وصفرُ قياسٍ = خروج 4 لا نتيجة",
      "الظهور   (lag_pub) : n=2" in _pgp_out and _pgp_rc4 == 4,
      _pgp_out[:200])

# PGP5 — 🔒 وصلةُ الـworkflow (درسُ `BT_CANDLE`): المدخلان ⟶ بيئةٌ يقرؤها
#   السكربت · بلا كرون · قراءةٌ فقط · والمفتاحُ يُمرَّر.
_pgp_wf = _yaml_pg.safe_load(open(".github/workflows/provider_gap.yml",
                                  encoding="utf-8"))
_pgp_steps = _pgp_wf["jobs"]["gap"]["steps"]
_pgp_env = next((st.get("env") or {} for st in _pgp_steps
                 if "PG_RUN_MIN" in str(st.get("env") or "")), {})
check("🕐 PGP5 مدخلا run_min/symbols ⟶ PG_RUN_MIN/PG_SYMS · بلا كرون · "
      "قراءةٌ فقط · والمفتاحُ مُمرَّر",
      "inputs.run_min" in str(_pgp_env.get("PG_RUN_MIN", ""))
      and "inputs.symbols" in str(_pgp_env.get("PG_SYMS", ""))
      and "POLYGON_API_KEY" in str(_pgp_env)
      and "cron" not in str(_pgp_wf.get(True) or _pgp_wf.get("on"))
      and _pgp_wf.get("permissions", {}).get("contents") == "read"
      and any("provider_gap_probe.py" in str(st.get("run") or "")
              for st in _pgp_steps),
      f"env={sorted(_pgp_env)}")

# ═══════════════════════════════════════════════════════════════════════════
# 🕐 **WCD1-WCD4 — «الإسقاطُ بساعة الحائط لا بالموضع»** (أمرُ المالك «نفّذ»
#    2026-08-26 بعد «قس فجوة المزود» — `provider_gap_result.md`): آخرُ صفٍّ في
#    ردّ المزوّد أحدثُ **مكتملةٍ** تُنشَر خلال ‏≈2-3 ثوانٍ، وقاعدةُ `rows[:-1]`
#    كانت تُسقطها موضعًا ⇒ ‏≈62ث ثابتةً لكلّ كشفٍ والرقيقُ يعلق دقائق.
#    ⇒ المسارُ الحيّ (`scan_liq_stages`) يمرّر `now_ms` فتُسقَط المتكوّنةُ
#    **زمنًا** · وبلا `now_ms` القاعدةُ القديمة **بت-بت** (أدواتُ الإعادة
#    المجمّدة — أرقامُ ‏44,200 مِرساةً محسوبةٌ عليها).
# ═══════════════════════════════════════════════════════════════════════════
_wcd_t0 = 1_756_000_000_000
_wcd_bars = [{"t": _wcd_t0 + _i * 60_000, "o": 1.0, "h": 1.1, "l": 0.99,
              "c": 1.06, "v": 3000} for _i in range(7)]
_wcd_last_t = _wcd_t0 + 7 * 60_000
_wcd_bars.append({"t": _wcd_last_t, "o": 1.0, "h": 1.3, "l": 1.0,
                  "c": 1.25, "v": 90_000})          # المؤهَّلةُ = آخرُ صفّ
_wcd_close = _wcd_last_t + 60_000
_wcd_g = int(S.LIQ_BAR_CLOSE_GUARD_MS)
_wcd_none = [e["stage"] for e in S.liq_stage_events(_wcd_bars, {})[0]]
_wcd_ev1, _wcd_st1 = S.liq_stage_events(
    _wcd_bars, {}, now_ms=_wcd_close + _wcd_g + 1_000)
_wcd_early = [e["stage"] for e in S.liq_stage_events(
    _wcd_bars, {}, now_ms=_wcd_last_t + 30_000)[0]]
check("🕐 WCD1 ثلاثةُ عوالم تفترق: بلا now_ms ⇒ آخرُ صفٍّ يُسقَط موضعًا (صمت "
      "بت-بت) · بساعةٍ بعد الإغلاق+الهامش ⇒ **M1 يفير على آخر صفّ** (حالة "
      "$CRE بعينها) · وبساعةٍ داخل دقيقتها ⇒ صمت (متكوّنةٌ زمنًا)",
      _wcd_none == [] and [e["stage"] for e in _wcd_ev1] == ["M1"]
      and _wcd_st1.get("anchor_ms") == _wcd_last_t and _wcd_early == [],
      f"none={_wcd_none} wall={[e['stage'] for e in _wcd_ev1]} "
      f"early={_wcd_early}")
# WCD2 — 🔒 **فحصُ تخوم الهامش** (درسُ «القفلُ لا يحرس إلّا بقدر ما تُفرِّق
#   عيّنتُه»): أغلقت قبل 4ث ⇒ ما زالت خارجًا · وعند الهامش بالضبط ⇒ داخلة
#   (`<=`) — والهامشُ فوق أقصى نشرٍ مقيس (‏p90 ‏≈4.2ث) ودون 30ث.
check("🕐 WCD2 تخومُ `LIQ_BAR_CLOSE_GUARD_MS`: إغلاقٌ قبل 4ث خارجٌ · وعند "
      "الهامش بالضبط داخلٌ · والقيمةُ فوق أقصى النشر المقيس (‏4.2ث) ودون 30ث",
      [e["stage"] for e in S.liq_stage_events(
          _wcd_bars, {}, now_ms=_wcd_close + 4_000)[0]] == []
      and [e["stage"] for e in S.liq_stage_events(
          _wcd_bars, {}, now_ms=_wcd_close + _wcd_g)[0]] == ["M1"]
      and 4_200 < _wcd_g <= 30_000,
      f"هامش={_wcd_g}ms")
# WCD3 — 🔒 **الوصلةُ من نقطة النداء الحيّة** (wire-check): `scan_liq_stages`
#   يمرّر `now_ms` فعلًا (بالـAST) · وسلوكيًّا: مسحٌ بساعةٍ بعد الإغلاق يلتقط
#   مِرساةً آخرَ صفٍّ (مستحيلٌ بالقاعدة القديمة) · وبساعةٍ داخل الدقيقة يصمت.
_wcd_calls = [c for c in _ast0.walk(_ast0.parse(
    _insp0.getsource(S.scan_liq_stages)))
    if isinstance(c, _ast0.Call)
    and getattr(c.func, "id", None) == "liq_stage_events"]
_wcd_scan = S.scan_liq_stages(
    [{"symbol": "WC1", "src": "تحت المتابعة"}], "2026-08-26", seen={},
    workers=1, fetch_bars=lambda s, minutes=65: _wcd_bars,
    clock=lambda: (_wcd_close + _wcd_g + 1_000) / 1000.0)
_wcd_scan2 = S.scan_liq_stages(
    [{"symbol": "WC1", "src": "تحت المتابعة"}], "2026-08-26", seen={},
    workers=1, fetch_bars=lambda s, minutes=65: _wcd_bars,
    clock=lambda: (_wcd_last_t + 30_000) / 1000.0)
# ⚠️ وصولٌ محروس — قفلٌ يفهرس `[0][0][1]` مباشرةً **ينهار** على مسحٍ صامتٍ
#    فيكتم كلَّ قفلٍ بعده (صنفُ «القفل المنهار» — أمسكته طفرةُ m1 فعلًا).
_wcd_m1 = ([e["stage"] for e in _wcd_scan[0][0][1]]
           if _wcd_scan[0] else ["⛔ مسحٌ صامت"])
check("🕐 WCD3 المسحُ الحيّ يمرّر `now_ms` (بالـAST) ⇒ مِرساةُ آخرِ صفٍّ تُلتقَط "
      "في الدورة نفسِها (‏كرتُ $CRE كان سيصل قبل ‏≈دقيقة) · وداخل الدقيقة يصمت",
      len(_wcd_calls) == 1
      and any(k.arg == "now_ms" for k in _wcd_calls[0].keywords)
      and _wcd_m1 == ["M1"]
      and _wcd_scan2[0] == [],
      f"نداءات={len(_wcd_calls)} · مسح={_wcd_m1}")
# WCD4 — 🔒 **أدواتُ الإعادة المجمّدة لا تعرف `now_ms`** (بالـAST على ملفَّيهما):
#   `kasih_scan.resolve` وكلُّ رقمٍ منشورٍ (‏44,200 مِرساة) على قاعدة الموضع ⇒
#   تمريرُ الساعة هناك يُبطل المقارنةَ مع كلّ ما نُشر (سابقة `CAP15`).
_wcd_frozen_ok = True
for _wcd_f in ("kasih_scan.py", "liq_case_probe.py", "m0_probe.py",
               "gate_probe.py", "alert_filter_check.py"):
    for _c in _ast0.walk(_ast0.parse(open(_wcd_f, encoding="utf-8").read())):
        if (isinstance(_c, _ast0.Call)
                and getattr(_c.func, "attr", getattr(_c.func, "id", None))
                == "liq_stage_events"
                and any(k.arg == "now_ms" or k.arg is None
                        for k in _c.keywords)):
            _wcd_frozen_ok = False
check("🕐 WCD4 أدواتُ الإعادة (kasih_scan/liq_case_probe) **بلا `now_ms`** "
      "بالـAST (ولا **kwargs) ⇒ قاعدةُ الموضع القديمة بت-بت فيهما",
      _wcd_frozen_ok
      and "rows[:-1]" in _insp0.getsource(S.liq_stage_events),
      f"frozen_ok={_wcd_frozen_ok}")

# 🪟🪟 **WIN1-WIN4 — «‏💪 شمعةٌ قوية · 🥉 ضعيف» في كرتٍ واحد (بلاغُ المالك على
#   `$SDOT`، مأخذُ المراجعة ح-1).** الوسمان **صادقان** وكلٌّ عن **نافذةٍ
#   أخرى**: الصنفُ من مجموع نافذةِ حدثه (‏`M30` ثلاثون دقيقةً تقرأ `strong`
#   بسهولة) والفئةُ من **الخمس** — والعلّةُ أنهما لم يُنسَبا إلى نافذتيهما،
#   وأن الصنفَ كان من **آخر** حدثٍ والفئةَ من **أوّل** حاملٍ ⇒ **يتبدّل
#   الوسمُ بترتيب الحدثين**. مقيسٌ قبل الإصلاح: `[M5, M30]` ⟶ «قوية · ضعيف»
#   وعكسُه ⟶ «وسط · ضعيف».
_wn_t = 1_755_000_000_000
_wn_k2w = {"c3": "نقضت", "c4": "خضراء 0-1", "v2": "المرساة فوق 30%",
           "v3": "سيولةٌ نازحة"}


def _wn_ev(stage, usd, mn):
    return {"stage": stage, "usd": usd, "minutes": mn, "span": mn,
            "anchor_ms": _wn_t, "last_ms": _wn_t + (mn - 1) * 60_000,
            "price": 1.10 + mn * 0.005, "price_ms": _wn_t + (mn - 1) * 60_000,
            "vol_x": 4.0, "class": S._ignition_candle_class(usd),
            "prev_close": 1.00, "anchor_price": 1.05, "anchor_low": 1.00,
            "k2": dict(_wn_k2w)}


_wn_m5, _wn_m30 = _wn_ev("M5", 60_000, 5), _wn_ev("M30", 400_000, 30)
_wn_px = {"stage": "Px", "usd": 80_000, "minutes": 1, "anchor_ms": _wn_t,
          "last_ms": _wn_t + 9 * 60_000, "price": 1.55,
          "price_ms": _wn_t + 9 * 60_000, "prev_usd": 60_000,
          "pulse_pct": 33.0, "k2": dict(_wn_k2w),
          "anchor_price": 1.05, "anchor_low": 1.00}
_wn_head = lambda evs: S.build_liq_stage_alert(          # noqa: E731
    [({"symbol": "WNT"}, evs)], now_ms=_wn_t + 30 * 60_000).splitlines()[0]
_wn_a, _wn_b = _wn_head([_wn_m5, _wn_m30]), _wn_head([_wn_m5])
check("🪟 WIN1 **كلُّ صنفٍ يُنسَب إلى نافذته** — والعيّنةُ تفرّق: `[M5,M30]` "
      "⟶ «30د» و`[M5]` وحدَه ⟶ «5د»",
      "💪 شمعةٌ قوية 30د" in _wn_a and "⚖️ شمعةٌ وسط 5د" in _wn_b
      and "30د" not in _wn_b, _wn_a[-70:])
check("🪟 WIN2 والفئةُ تُسمّي نافذتَها (‏5د) — فلا يُقرأ الوسمان تناقضًا",
      "🥉 ضعيف (5د)" in _wn_a and "🥉 ضعيف (5د)" in _wn_b, _wn_a[-70:])
check("🪟 WIN3 الصنفُ من **أحدثِ حاملٍ** لا من آخر حدث: كرتُ `[M5, Px]` "
      "يُبقي وسمَ الخمس (‏`Px` بلا `class` بالبناء) ولا يفقده",
      "⚖️ شمعةٌ وسط 5د" in _wn_head([_wn_m5, _wn_px])
      and S._ignition_candle_class is not None
      and "class" not in _wn_px, _wn_head([_wn_m5, _wn_px])[-70:])
check("🪟 WIN4 وكرتُ `Px` وحدَه: **بلا وسمِ صنفٍ إطلاقًا** (لا يُخترَع صنفٌ "
      "لحدثٍ لا يحمله) والفئةُ تبقى",
      not any(_c in _wn_head([_wn_px]) for _c in S._LIQ_CLS_AR.values())
      and "🥉 ضعيف (5د)" in _wn_head([_wn_px]), _wn_head([_wn_px])[-70:])

# STOP1 — **الوصلةُ من المِرساة إلى الكرت** (درسُ wire-check): `anchor_low`
#   يُكتَب في الحالة وفي حدثَي M1 وM5 — ويُقرأ في السطر. فارقٌ محدَّد.
_st_bars = [{"t": _br_t - 60_000 * (12 - i), "o": 1.00, "h": 1.01, "l": 0.99,
             "c": 1.00, "v": 500} for i in range(12)]
_st_bars += [{"t": _br_t, "o": 1.00, "h": 1.30, "l": 0.97, "c": 1.29,
              "v": 40_000},
             {"t": _br_t + 60_000, "o": 1.29, "h": 1.31, "l": 1.28,
              "c": 1.30, "v": 20_000}]
_st_ev, _st_st = S.liq_stage_events(_st_bars)
_st_m1 = next((e for e in _st_ev if e.get("stage") == "M1"), {})
check("🛑 STOP1 `anchor_low` يُكتَب في الحالة وفي حدث M1 من **قاع شمعة "
      "المِرساة** (‏0.97) — وصلةٌ حيّةٌ لا مفتاحٌ متخيَّل",
      _st_st.get("anchor_low") == 0.97 and _st_m1.get("anchor_low") == 0.97
      and _st_m1.get("anchor_price") == 1.29,
      f"حالة={_st_st.get('anchor_low')} · M1={_st_m1.get('anchor_low')}")

# STOP2 — السطرُ يظهر مع المستوى ويغيب بدونه (حالةٌ قديمة) · والمسافةُ صحيحة.
_st_l = S.liq_stop_line({"anchor_low": 0.1105, "anchor_price": 0.1261})
_st_bare = S.liq_stop_line({"anchor_price": 0.1261})
check("🛑 STOP2 سطرُ الوقف حاضرٌ مع المستوى وغائبٌ بدونه · وبالمسافة الصحيحة "
      "(‏0.1261 ⟶ 0.1105 = 14.1%)",
      "$0.1105" in _st_l and "14.1%" in _st_l
      and "قاعُ شمعة المِرساة" in _st_l
      and _st_bare == "" and S.liq_stop_line({}) == ""
      and S.liq_stop_line({"anchor_low": "س"}) == "",
      _st_l[:90])

# STOP3 — 🔒 **نظامٌ خامسٌ يُسمّى ولا يختلط بالأربعة**: السطرُ يقول «وقفُ
#   الجلسة» و«قاعُ شمعة المِرساة» — ولا يذكر 7% ولا −6% ولا ذيلَ الشمعة.
check("🛑 STOP3 الوقفُ يسمّي نظامَه ولا يستورد وقفًا من نظامٍ آخر",
      "وقفُ الجلسة" in _st_l
      and not any(_w in _st_l for _w in ("7%", "6%", "ذيل", "الدعم")),
      _st_l[:90])

# STOP4 — 🔒 **عرضٌ لا قرار**: الوقفُ خارج الجذور · ولا يمسّ `rr` ولا الوقفَ
#   الإنتاجيّ (`STOP_BELOW_LOW_PCT` جذرٌ مقفول).
check("🛑 STOP4 الوقفُ عرضٌ لا قرار: خارج الجذور ولا يمسّ وقفَ الارتكاز",
      all("liq_stop_line" not in _insp0.getsource(getattr(S, _f))
          for _f in ("rank_key", "select_top", "classify_tier", "entry_status",
                     "analyze_ticker", "scan_market", "backtest_symbol",
                     "alert_filter_keep"))
      and "STOP_BELOW_LOW_PCT" not in _insp0.getsource(S.liq_stop_line)
      and S.CONFIG["STOP_BELOW_LOW_PCT"] == (5, 7),
      "")

# STOP5 — 🔴🔴 **الوصلةُ الحيّة إلى كرت M5 — كشفَتها الطفرةُ لا القراءة**
#   (‏2026-08-20): `STOP1` يفحص حدثَ `M1` و`STOP2` يفحص الدالّةَ على **قاموسٍ
#   مصنوعٍ باليد** ⇒ **نزعُ `anchor_low` من حدث `M5`/`M30` كان يمرّ أخضر**
#   بينما سطرُ الوقف **يختفي من الكرت الذي يصل المالكَ فعلًا** (‏كرتُ M5 هو
#   حاملُ الوقف). صنفُ «الفِكستشرُ الذي يكذب» بعينه ⇒ القفلُ يبني الحدثَ
#   **بدالّة الإنتاج نفسِها** بالنمط القانونيّ (نافذةٌ متنامية بحالةٍ محمولة —
#   `kasih_scan.first_anchor` حرفيًّا) ثم يقرأ الكرتَ المبنيّ.
_s5_bars = [{"t": _br_t - 60_000 * (12 - i), "o": 1.00, "h": 1.01, "l": 0.99,
             "c": 1.00, "v": 500} for i in range(12)]
_s5_bars += [{"t": _br_t, "o": 1.00, "h": 1.30, "l": 0.97, "c": 1.29,
              "v": 40_000}]
_s5_bars += [{"t": _p13_t + 60_000 * _k, "o": 1.29, "h": 1.31, "l": 1.28,
              "c": 1.30, "v": 20_000} for _k in range(1, 8)]
_s5_st = {}
_s5_evs = []
for _s5_k in range(3, len(_s5_bars) + 1):
    _s5_e, _s5_st = S.liq_stage_events(_s5_bars[:_s5_k], _s5_st)
    _s5_evs += (_s5_e or [])
_s5_m5 = next((e for e in _s5_evs if e.get("stage") == "M5"), {})
_s5_msg = (S.build_liq_stage_alert(
    [({"symbol": "TST", "src": "تحت المتابعة"}, [_s5_m5])],
    now_ms=_br_t + 500_000) if _s5_m5 else "")
check("🛑 STOP5 حدثُ M5 **الحيّ** يحمل anchor_low · والكرتُ يطبع سطرَ الوقف",
      _s5_m5.get("anchor_low") == 0.97
      and "🛑 وقفُ الجلسة" in _s5_msg and "$0.97" in _s5_msg,
      f"M5={_s5_m5.get('anchor_low')} · مراحل="
      f"{[e.get('stage') for e in _s5_evs]}")

# ═══ 🛑📊 T-EXIT-STOP — أقفال أداةِ القياس ES1-ES8 (2026-08-20) ═══
# 🔒 قراءة/قياسٌ فقط · العقد `exit_stop_prereg.md` مدفوعٌ قبل أيّ رقم.
import ast as _es_ast
import importlib.util as _es_iu

_ES_SRC = open("exit_stop_arms.py", encoding="utf-8").read()
_ES_TREE = _es_ast.parse(_ES_SRC)

# ES1 — 🔒 **مقياسٌ واحدٌ لا اثنان**: كشفُ المِرساة والحسمُ من `kasih_scan`
#   **بالاسم**، وخصائصُ التصنيف من `kasih2_scan` بالاسم. نسخُ أيٍّ منها هنا
#   كان سيصنع مقياسًا ثانيًا يتفرّق عن أرقامنا المنشورة صامتًا.
_es_calls = {
    f"{getattr(n.func.value, 'id', '')}.{n.func.attr}"
    for n in _es_ast.walk(_ES_TREE)
    if isinstance(n, _es_ast.Call)
    and isinstance(n.func, _es_ast.Attribute)
    and isinstance(getattr(n.func, "value", None), _es_ast.Name)
}
check("🛑 ES1 مقياسٌ واحد: first_anchor/resolve/f2_usd5 من kasih_scan بالاسم",
      {"KS.first_anchor", "KS.resolve", "KS.f2_usd5", "KS.prescreen",
       "KS.parse_day", "KS.wilson"} <= _es_calls
      and {"K2.j1_bucket", "K2.c3_bucket", "K2.c4_bucket", "K2.v2_bucket",
           "K2.v3_bucket"} <= _es_calls,
      str(sorted(x for x in _es_calls if x.startswith(("KS.", "K2."))))[:150])

_es_spec = _es_iu.spec_from_file_location("_es_mod", "exit_stop_arms.py")
_es_mod = _es_iu.module_from_spec(_es_spec)
_es_spec.loader.exec_module(_es_mod)

# ── عيّنةٌ مصطنعة: (t, o, h, lo, c, v) بدقائقَ متتالية ─────────────────────
_A = 1_700_000_000_000                      # لحظةُ المِرساة
_M = 60_000


def _es_bar(k, o, h, lo, c, v=1000):
    return (_A + k * _M, o, h, lo, c, v)


# قبلَ المِرساة: قاعان (‏−15..−1) · ثم المِرساةُ · ثم نافذةُ الخمس · ثم مسار
_ES_ROWS = (
    [_es_bar(-15, 1.00, 1.02, 0.80, 1.00)]          # أعمقُ قاعٍ قبل المِرساة
    + [_es_bar(k, 1.00, 1.02, 0.95, 1.00) for k in range(-14, -1)]
    + [_es_bar(-1, 1.00, 1.02, 0.90, 1.00)]         # الشمعةُ السابقة (S2=0.90)
    + [_es_bar(0, 1.00, 1.30, 0.97, 1.28)]          # المِرساة (S0=0.97)
    + [_es_bar(1, 1.28, 1.30, 0.93, 1.29)]          # داخل الخمس (S1=0.93)
    + [_es_bar(k, 1.29, 1.31, 1.20, 1.30) for k in (2, 3, 4)]
    + [_es_bar(5, 1.30, 1.40, 1.25, 1.35)]
    + [_es_bar(6, 1.35, 1.80, 1.30, 1.75)]          # لمسُ +30% من e5=1.30
)

# ES2 — 🔒 **الأذرعُ الأربعُ تفرّق فعلًا** (حارسُ `no-op` — بصمةُ `BT_CANDLE`)
