# سلوكيّ — `_maybe_chain` من نقطة النداء: إطلاقٌ واحدٌ · لا إطلاقَ قبل الحدّ · حضورُ عاملٍ يمنع
_ch_calls = []
def _ch_api(runs):
    def _f(m, p, b=None):
        _ch_calls.append((m, p, b))
        return {"workflow_runs": runs} if m == "GET" else {}
    return _f
_ch_env0 = dict(_ch_os.environ)
